public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns messages in a topic in a forum supergroup chat or a chat with a bot with topics. The messages are returned in reverse chronological order
    /// (i.e., in order of decreasing message_id). For optimal performance, the number of returned messages is chosen by TDLib
    /// </summary>
    public Task<TdLib.TdApi.Objects.Messages> GetForumTopicHistoryAsync(long chatId = default, int forumTopicId = default, long fromMessageId = default, int offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("GetForumTopicHistoryAsync", typeof(GetForumTopicHistory).FullName ?? "GetForumTopicHistoryAsync");

           try
           {
             return client.GetForumTopicHistoryAsync(chatId, forumTopicId, fromMessageId, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
